// Function to count words in a string
function countWords(str) {
  if (!str) return 0;
  // Remove basic HTML tags if any, clean up whitespace, and count split words
  const cleanText = str.replace(/<[^>]*>/g, ' ').trim();
  return cleanText ? cleanText.split(/\s+/).length : 0;
}

// Filter items with 100 words or more, then take the first match
const matchedItem = $input.all().find(item => {
  const text = item.json.contentSnippet || item.json.content || '';
  return countWords(text) >= 100;
});

// Return the matched item structured as expected, or an empty array if none match
if (matchedItem) {
  return [{
    json: {
      title: matchedItem.json.title,
      selftext: matchedItem.json.contentSnippet || matchedItem.json.content || '',
      link: matchedItem.json.link,
      wordCount: countWords(matchedItem.json.contentSnippet || matchedItem.json.content || '')
    }
  }];
}

return [];

// One Flow project per run, so folders from different runs never mix.
const items = $input.all();
const project = 'comedy-' + new Date().toISOString().replace(/[:.]/g, '-');
const scenes = items.map((i) => ({ prompt: i.json.image_prompt, type: 'image', aspect_ratio: '3:4' }));
return [{ json: { body: { project, scenes } } }];

// Pair each finished image with its scene (same order). Stops the run with a clear message if any scene has no image.
const wait = $input.first().json;
const scenes = $('Split Out').all();
const jobs = wait.jobs || [];
if (jobs.length !== scenes.length) throw new Error(`Flow returned ${jobs.length} jobs for ${scenes.length} scenes`);
const failed = jobs.filter((j) => j.status !== 'done' || !j.files || !j.files.length);
if (failed.length) throw new Error('Flow could not make an image for job(s): ' + failed.map((j) => j.scene || j.id).join(', ') + '. Images cost no credits, so run again.');
return scenes.map((s, i) => ({ json: { ...s.json, flow_file: jobs[i].files[0] } }));
